// Syntax-highlights the code shown on the site at build time, so no
// highlighter ships to the browser. Edit snippets here, then run
// `npm run snippets` and commit the generated file.
import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import { codeToTokens } from 'shiki';

const OUTPUT = path.resolve(
  import.meta.dirname,
  '../src/pages/snippets.generated.ts',
);
// Code always sits on the dark --color-code-bg, so one dark theme serves both
// site themes; every colour in it clears 4.5:1 on that background
const THEME = 'github-dark-default';

// From FitMySpace: src/components/design-system/ui/Button/Button.types.ts
const BUTTON_TYPES = `type ButtonWithChildren = ButtonBaseProps & {
  children: ReactNode;
  'aria-label'?: string;
};

type ButtonIconOnly = ButtonBaseProps & {
  children?: never;
  'aria-label': string; // required: nothing else names the button
};

export type ButtonProps = ButtonWithChildren | ButtonIconOnly;

// ✗ Type error: property 'aria-label' is missing
<Button variant="secondary" appearance="outline" size="sm" icon={<Trash2 />} />

// ✓ Compiles
<Button variant="secondary" appearance="outline" size="sm" icon={<Trash2 />}
  aria-label="Remove from list" />`;

// From FitMySpace: the generated tokens.css and Button.module.css
const TOKEN_OUTPUTS = [
  '--ds-color-sage-700: #335f3f;',
  '--ds-semantic-color-background-brand-base: var(--ds-color-sage-700);',
  '--ds-component-button-primary-fill-background-default: var(--ds-semantic-color-background-brand-base);',
  '.fill-primary { background-color: var(--ds-component-button-primary-fill-background-default); }',
];

/** Lines of [text, colour], with neighbouring same-colour tokens merged */
async function highlight(code, lang) {
  const { tokens } = await codeToTokens(code, { lang, theme: THEME });
  return tokens.map((line) =>
    line.reduce((merged, { content, color }) => {
      const last = merged[merged.length - 1];
      if (last && last[1] === color) {
        last[0] += content;
      } else {
        merged.push([content, color]);
      }
      return merged;
    }, []),
  );
}

/** A bare declaration only tokenises inside a rule, so wrap it and unwrap it */
async function highlightCssLine(line) {
  if (!line.startsWith('--')) {
    return (await highlight(line, 'css'))[0];
  }
  const [, inner] = await highlight(`:root {\n${line}\n}`, 'css');
  return inner;
}

const buttonTypes = await highlight(BUTTON_TYPES, 'tsx');
const tokenOutputs = await Promise.all(TOKEN_OUTPUTS.map(highlightCssLine));

await writeFile(
  OUTPUT,
  `// Generated by scripts/highlight-snippets.mjs; edit the snippets there
import type { CodeLine } from '@/types';

export const buttonTypes: CodeLine[] = ${JSON.stringify(buttonTypes)};

export const tokenOutputs: CodeLine[] = ${JSON.stringify(tokenOutputs)};
`,
);
console.log(`Wrote ${path.relative(process.cwd(), OUTPUT)}`);
